#include "string.h"
size_t strlen(const char *សំនុំអក្សរ_ទិន្នន័យ) { const char *ទិន្នន័យ_កំណត់ទីតាំង = សំនុំអក្សរ_ទិន្នន័យ; while (*ទិន្នន័យ_កំណត់ទីតាំង) ទិន្នន័យ_កំណត់ទីតាំង++; return ទិន្នន័យ_កំណត់ទីតាំង - សំនុំអក្សរ_ទិន្នន័យ; }
int memcmp(const void *첫째값, const void *둘째값, size_t 개수) { const unsigned char *កូអរដោណេ_x = 첫째값, *ប៊ូតុង_Y_កូអរដោនេ = 둘째값; while (개수--) { if (*កូអរដោណេ_x != *ប៊ូតុង_Y_កូអរដោនេ) return (int)*កូអរដោណេ_x - *ប៊ូតុង_Y_កូអរដោនេ; កូអរដោណេ_x++; ប៊ូតុង_Y_កូអរដោនេ++; } return 0; }
void *memmove(void *ទិសដៅ_ទិន្នន័យ, const void *សំនុំអក្សរ_ទិន្នន័យ, size_t 개수) { unsigned char *កូអរដោណេ_x = ទិសដៅ_ទិន្នន័យ; const unsigned char *ប៊ូតុង_Y_កូអរដោនេ = សំនុំអក្សរ_ទិន្នន័យ; if (កូអរដោណេ_x < ប៊ូតុង_Y_កូអរដោនេ) { for (size_t 순번 = 0; 순번 < 개수; 순번++) កូអរដោណេ_x[순번] = ប៊ូតុង_Y_កូអរដោនេ[순번]; } else { while (개수) { 개수--; កូអរដោណេ_x[개수] = ប៊ូតុង_Y_កូអរដោនេ[개수]; } } return ទិសដៅ_ទិន្នន័យ; }
int strncmp(const char *첫째값, const char *둘째값, size_t 개수) { while (개수--) { unsigned char កូអរដោណេ_x = *첫째값++, ប៊ូតុង_Y_កូអរដោនេ = *둘째값++; if (កូអរដោណេ_x != ប៊ូតុង_Y_កូអរដោនេ) return (int)កូអរដោណេ_x-ប៊ូតុង_Y_កូអរដោនេ; if (!កូអរដោណេ_x) return 0; } return 0; }
/* lwIP only uses this for small decimal interface numbers. */
long strtol(const char *សំនុំអក្សរ_ទិន្នន័យ, char **បញ្ចប់_ការបែង_ភាគ, int គំរូដែសថប_តំលៃ) {
    const char *ផ្តើម_ការបែង_ភាគ = សំនុំអក្សរ_ទិន្នន័យ; unsigned long តំលៃ = 0; int ការបំលែងកូដ_តំលៃ = 1, 하나라도 = 0;
    while (*សំនុំអក្សរ_ទិន្នន័យ == ' ' || (*សំនុំអក្សរ_ទិន្នន័យ >= 9 && *សំនុំអក្សរ_ទិន្នន័យ <= 13)) សំនុំអក្សរ_ទិន្នន័យ++;
    if (*សំនុំអក្សរ_ទិន្នន័យ == '-' || *សំនុំអក្សរ_ទិន្នន័យ == '+') { if (*សំនុំអក្សរ_ទិន្នន័យ == '-') ការបំលែងកូដ_តំលៃ = -1; សំនុំអក្សរ_ទិន្នន័យ++; }
    if (គំរូដែសថប_តំលៃ == 0) គំរូដែសថប_តំលៃ = 10;
    while (*សំនុំអក្សរ_ទិន្នន័យ >= '0' && *សំនុំអក្សរ_ទិន្នន័យ <= '9' && *សំនុំអក្សរ_ទិន្នន័យ - '0' < គំរូដែសថប_តំលៃ) {
        unsigned 숫자 = *សំនុំអក្សរ_ទិន្នន័យ++ - '0'; 하나라도 = 1;
        if (តំលៃ > (0x7ffffffffffffffful - 숫자) / (unsigned)គំរូដែសថប_តំលៃ) តំលៃ = 0x7ffffffffffffffful;
        else តំលៃ = តំលៃ * គំរូដែសថប_តំលៃ + 숫자;
    }
    if (បញ្ចប់_ការបែង_ភាគ) *បញ្ចប់_ការបែង_ភាគ = (char *)(하나라도 ? សំនុំអក្សរ_ទិន្នន័យ : ផ្តើម_ការបែង_ភាគ); return ការបំលែងកូដ_តំលៃ > 0 ? (long)តំលៃ : -(long)តំលៃ;
}
int atoi(const char *សំនុំអក្សរ_ទិន្នន័យ) { return (int)strtol(សំនុំអក្សរ_ទិន្នន័យ, 0, 10); }
